// Modelo de Duración (copiado de durA_modelo.js — editar allá y regenerar con durA_construir.js)
/* durA_modelo.js — Modelo de «Duración» de Armoni (contrato dura v1, ver durA_contrato.md)
 * Función pura, sin dependencias: corre igual en Node (tests) y dentro de un nodo Code de n8n.
 *
 * calcularDuracion({ hoy, productos, compras }) → { v, hoy, productos: { idSinGuiones: dura }, global }
 *   productos: [{ id, nombre, grupo, falta, marcadoEl, acaboEl }]          (Mercado - Productos)
 *   compras:   [{ productoId, fecha:'YYYY-MM-DD', nombre, cantidad?, acaboAnterior? }]   (Mercado - Compras; nombre trae « · detalle »)
 *              acaboAnterior opcional: día en que se acabó la compra anterior (lo que marcaba «Marcado el» al registrar).
 *              cantidad opcional: número (multiplica el detalle) o texto ("2 libras").
 */
function calcularDuracion(entrada) {
  'use strict';
  const SEP = ' · ';
  const hoy = String(entrada.hoy || '').slice(0, 10);
  const productos = Array.isArray(entrada.productos) ? entrada.productos : [];
  const compras = Array.isArray(entrada.compras) ? entrada.compras : [];

  /* ── utilidades de fecha ── */
  const esFecha = f => /^\d{4}-\d{2}-\d{2}$/.test(String(f || '').slice(0, 10));
  const f10 = v => { if (!v) return null; if (typeof v === 'object') v = v.start || v.date || ''; const t = String(v).slice(0, 10); return esFecha(t) ? t : null; };
  const ms = f => Date.parse(f + 'T12:00:00Z');
  const dif = (a, b) => Math.round((ms(b) - ms(a)) / 864e5);
  const suma = (f, n) => new Date(ms(f) + Math.round(n) * 864e5).toISOString().slice(0, 10);
  const idc = id => String(id || '').replace(/-/g, '').toLowerCase();
  const norm = t => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
  const baseNom = n => String(n || '').split(SEP)[0].trim();
  const detNom = n => { const s = String(n || ''), k = s.indexOf(SEP); return k < 0 ? '' : s.slice(k + SEP.length).trim(); };
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const MES_C = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
  const nomMes = m => MESES[+m.slice(5, 7) - 1];
  const fCorta = f => (+f.slice(8, 10)) + ' ' + MES_C[+f.slice(5, 7) - 1];
  const DIAS_S = ['domingos', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábados'];

  /* ── estadística ── */
  const mediana = a => { const s = a.slice().sort((x, y) => x - y), n = s.length; return n ? (n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2) : null; };
  const binomCola = (k, n, p) => { // P(X >= k)
    let t = 0; for (let i = k; i <= n; i++) { let c = 1; for (let j = 0; j < i; j++) c = c * (n - j) / (j + 1); t += c * Math.pow(p, i) * Math.pow(1 - p, n - i); } return t;
  };
  const r1 = x => Math.round(x * 10) / 10;

  /* ── cantidades: «2 libras», «1/2 kilo», «x3», «2 de 500 g», «una docena», «30 huevos» ── */
  const NUM_PAL = { un: 1, uno: 1, una: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5, seis: 6, siete: 7, ocho: 8, nueve: 9, diez: 10, doce: 12, quince: 15, veinte: 20, treinta: 30, medio: .5, media: .5 };
  const UNI = [ // [regex, etiqueta, dimensión, factor a unidad base]
    [/^(lb|lbs|libras?)$/, 'lb', 'masa', 500], [/^(kg|kgs|kilos?|kilogramos?)$/, 'kg', 'masa', 1000], [/^(g|gr|grs|gramos?)$/, 'g', 'masa', 1],
    [/^(arrobas?)$/, 'arroba', 'masa', 12500], [/^(ml|cc|mililitros?)$/, 'ml', 'vol', 1], [/^(l|lt|lts|litros?)$/, 'l', 'vol', 1000],
    [/^(galon|galones)$/, 'galón', 'vol', 3785], [/^(docenas?)$/, 'unid', 'unid', 12], [/^(cubetas?)$/, 'unid', 'unid', 30],
    [/^(u|und|unds|unid|unidad|unidades)$/, 'unid', 'unid', 1],
    [/^(paquetes?|paq|bolsas?|cajas?|tarros?|botellas?|frascos?|latas?|rollos?|pacas?|sobres?|barras?)$/, null, 'paq', 1]
  ];
  const ETQ = { lb: ['libra', 'libras'], kg: ['kilo', 'kilos'], g: ['gramo', 'gramos'], arroba: ['arroba', 'arrobas'], ml: ['ml', 'ml'], l: ['litro', 'litros'], 'galón': ['galón', 'galones'], unid: ['unidad', 'unidades'] };
  const numTxt = s => { s = s.replace(',', '.'); if (s === '½') return .5; if (/^\d+\/\d+$/.test(s)) { const [a, b] = s.split('/').map(Number); return b ? a / b : null; } const n = parseFloat(s); return isFinite(n) ? n : (s in NUM_PAL ? NUM_PAL[s] : null); };
  const singular = w => w.replace(/(es|s)$/, '') || w;
  function leeCantidad(texto) {
    let t = norm(texto).replace(/½/g, ' ½ ').replace(/(\d)\s*([a-z])/g, '$1 $2');
    if (!t) return null;
    let mult = 1, m;
    if ((m = t.match(/(?:^|\s)x\s*(\d+)\b|\b(\d+)\s*x(?:\s|$)/))) { mult = +(m[1] || m[2]); t = t.replace(m[0], ' ').trim(); }
    const tok = t.split(/\s+/).filter(Boolean);
    let n = null, u = null, extra = 0;
    for (let i = 0; i < tok.length; i++) {
      const v = numTxt(tok[i]);
      if (v != null && n == null) { n = v; continue; }
      if (v != null && n != null && u == null && tok[i - 1] === 'de') { n = n * v; continue; } // «2 de 500 g»
      if (tok[i] === 'y' && (tok[i + 1] === 'media' || tok[i + 1] === 'medio')) { extra = .5; i++; continue; }
      if (u == null && n != null) {
        const w = tok[i]; if (w === 'de') continue;
        const hit = UNI.find(x => x[0].test(w));
        if (hit) u = { etq: hit[1] || singular(w), dim: hit[2] === 'paq' ? 'paq:' + singular(w) : hit[2], f: hit[3] };
        else if (/^[a-z]{3,}$/.test(w)) u = { etq: 'unid', dim: 'unid', f: 1 };   // «30 huevos», «6 bananos»
      }
      if (u == null && n == null) { const hit = UNI.find(x => x[0].test(tok[i])); if (hit) { n = 1; u = { etq: hit[1] || singular(tok[i]), dim: hit[2] === 'paq' ? 'paq:' + singular(tok[i]) : hit[2], f: hit[3] }; } } // «libra y media», «docena»
    }
    if (n == null && mult === 1) return null;
    if (n == null) n = 1;
    n = (n + extra) * mult;
    if (!u) u = { etq: 'unid', dim: 'unid', f: 1 };
    if (u.dim === 'unid' && u.f !== 1) { n = n * u.f; u = { etq: 'unid', dim: 'unid', f: 1 }; }   // docena, cubeta → unidades
    if (!(n > 0) || n > 100000) return null;
    return { n, u: u.etq, dim: u.dim, base: n * u.f, f: u.f };
  }
  function cantidadCompra(c) {
    const det = detNom(c.nombre);
    const k = c.cantidad;
    if (typeof k === 'string' && k.trim()) { const q = leeCantidad(k); if (q) return q; }
    const qd = det ? leeCantidad(det) : null;
    if (typeof k === 'number' && k > 0) {
      if (qd) return Object.assign({}, qd, { n: qd.n * k, base: qd.base * k });
      return { n: k, u: 'unid', dim: 'unid', base: k, f: 1 };
    }
    return qd;
  }
  function fmtN(n) {
    if (Math.abs(n - .5) < .05) return '½';
    if (Math.abs(n - .25) < .03) return '¼';
    const e = Math.floor(n), fr = n - e;
    if (e >= 1 && Math.abs(fr - .5) < .05 && n < 10) return e + '½';
    return n >= 10 ? String(Math.round(n)) : String(r1(n)).replace('.', ',');
  }
  function textoCant(n, u) {
    const e = ETQ[u] || [u, u.endsWith('s') ? u : u + 's'];
    const plural = !(n <= 1);
    if (u === 'g' && n >= 1000) return fmtN(n / 1000) + (n >= 2000 ? ' kilos' : ' kilo');
    if (u === 'ml' && n >= 1000) return fmtN(n / 1000) + (n >= 2000 ? ' litros' : ' litro');
    return fmtN(n) + ' ' + (plural ? e[1] : e[0]);
  }

  /* ── agrupar compras por producto ── */
  const porNombre = {};
  productos.forEach(p => { porNombre[norm(baseNom(p.nombre))] = idc(p.id); });
  const comprasDe = {};
  for (const c of compras) {
    const f = f10(c.fecha); if (!f || (hoy && f > hoy)) continue;
    let id = idc(c.productoId);
    if (!id || id.length !== 32) id = porNombre[norm(baseNom(c.nombre))] || null;
    if (!id) continue;
    (comprasDe[id] = comprasDe[id] || []).push({ fecha: f, nombre: c.nombre || '', q: cantidadCompra(c), acaboAnt: f10(c.acaboAnterior), clave: f + '|' + norm(c.nombre) + '|' + (c.cantidad == null ? '' : c.cantidad) });
  }

  function eventos(lista) {
    const vistos = new Set(), dias = {};
    for (const c of lista) {
      if (vistos.has(c.clave)) continue;     // reintentos duplicados del mismo día y mismo nombre cuentan una vez
      vistos.add(c.clave);
      (dias[c.fecha] = dias[c.fecha] || []).push(c);
    }
    return Object.keys(dias).sort().map(f => ({ fecha: f, items: dias[f], acaboAnt: dias[f].map(c => c.acaboAnt).filter(Boolean).sort().pop() || null }));
  }

  /* ── un producto ── */
  function modelaProducto(p, prior) {
    const id = idc(p.id);
    const ev = eventos(comprasDe[id] || []);
    const falta = !!p.falta;
    const acabo = f10(p.acaboEl) || f10(p.marcadoEl);
    const vacio = {
      v: 1, estado: 'sin', fuente: null, dias: null, diasEstaVez: null, rango: null, confianza: 'baja', confianzaN: 0,
      datos: { compras: ev.length, intervalos: 0, usados: 0, descartados: 0 },
      tendencia: { dir: null, cambioPct: null, texto: null }, cantidad: null, porSemana: null, porMes: null, comprasPorMes: null,
      ultimaCompra: null, proxima: null, proximaRango: null, quedan: null, uso: null, nivel: null, acabo: null,
      historial: [], meses: [], mesMas: null, mesMenos: null, patron: null, nota: 'Todavía no hay compras registradas.'
    };
    if (!ev.length) return vacio;

    // cantidad por día de compra, en la dimensión más común
    const dimCuenta = {};
    ev.forEach(e => e.items.forEach(c => { if (c.q) dimCuenta[c.q.dim] = (dimCuenta[c.q.dim] || 0) + 1; }));
    const dim = Object.keys(dimCuenta).sort((a, b) => dimCuenta[b] - dimCuenta[a])[0] || null;
    const etqCuenta = {};
    ev.forEach(e => {
      const qs = e.items.map(c => c.q);
      e.base = dim && qs.every(q => q && q.dim === dim) ? qs.reduce((s, q) => s + q.base, 0) : null;
      qs.forEach(q => { if (q && q.dim === dim) etqCuenta[q.u + '|' + q.f] = (etqCuenta[q.u + '|' + q.f] || 0) + 1; });
    });
    const etqTop = Object.keys(etqCuenta).sort((a, b) => etqCuenta[b] - etqCuenta[a])[0];
    const [uMostrar, fMostrar] = etqTop ? [etqTop.split('|')[0], +etqTop.split('|')[1]] : [null, 1];
    const conQ = ev.filter(e => e.base != null);
    const qHab = conQ.length ? mediana(conQ.map(e => e.base)) : null;
    const rel = e => (qHab && e.base != null) ? Math.min(4, Math.max(.25, e.base / qHab)) : 1;
    const ult = ev[ev.length - 1];
    const rUlt = rel(ult);

    // observaciones: días que duró cada compra, normalizados a la cantidad habitual
    const obs = [];
    for (let i = 0; i + 1 < ev.length; i++) {
      // si al comprar se guardó el día en que se acabó la anterior, esa es la duración real (sin el tiempo en la canasta)
      const ac = ev[i + 1].acaboAnt, real = ac && ac >= ev[i].fecha && ac <= ev[i + 1].fecha;
      const g = dif(ev[i].fecha, real ? ac : ev[i + 1].fecha);
      if (g >= 1) obs.push({ i, g, r: rel(ev[i]), norm: g / rel(ev[i]), w: real ? 1.5 : 1, tipo: 'intervalo' });
    }
    let acaboObs = null;
    if (falta && acabo && acabo >= ult.fecha && (!hoy || acabo <= hoy)) {
      const g = dif(ult.fecha, acabo);
      if (g >= 1) { acaboObs = { i: ev.length - 1, g, r: rUlt, norm: g / rUlt, w: 1.5, tipo: 'acabo' }; obs.push(acaboObs); }
    }

    // atípicos: escala logarítmica, mediana y MAD
    const L = obs.map(o => Math.log(o.norm));
    const med = mediana(L);
    let mad = mediana(L.map(x => Math.abs(x - med)));
    obs.forEach((o, k) => {
      const x = L[k];
      if (obs.length >= 4) o.atipico = Math.abs(x - med) > Math.max(3 * 1.4826 * mad, Math.log(2.2));
      else if (obs.length === 3) { const otros = L.filter((_, j) => j !== k); o.atipico = Math.abs(x - mediana(otros)) > Math.log(3); }
      else o.atipico = false;
    });
    const usados = obs.filter(o => !o.atipico);

    // estimación ponderada: lo reciente pesa más (vida media de 3 compras)
    let dias = null, spred = null, fuente = null;
    if (usados.length) {
      const orden = usados.slice().sort((a, b) => b.i - a.i);
      let sw = 0, sx = 0;
      orden.forEach((o, rango) => { o.peso = o.w * Math.pow(.5, rango / 3); sw += o.peso; sx += o.peso * Math.log(o.norm); });
      const mu = sx / sw;
      let sv = 0; orden.forEach(o => { sv += o.peso * Math.pow(Math.log(o.norm) - mu, 2); });
      const k = usados.length, s0 = .35;
      const s2 = ((k > 1 ? sv / sw : 0) * k + 2 * s0 * s0) / (k + 2);
      spred = Math.sqrt(s2 * (1 + 1 / k));
      dias = Math.exp(mu);
      fuente = usados.some(o => o.tipo === 'intervalo') ? 'historial' : 'acabo';
    }
    // lleva más tiempo del esperado sin acabarse: es un mínimo, sube un poco la estimación
    const abierto = hoy && !falta ? dif(ult.fecha, hoy) : 0;
    if (dias && abierto / rUlt > dias && abierto / rUlt <= 2.5 * dias && usados.length < 6) {
      const k = usados.length; dias = Math.exp((k * Math.log(dias) + .5 * Math.log(abierto / rUlt)) / (k + .5));
    }
    if (!dias && prior) { dias = prior; spred = .6; fuente = 'grupo'; }

    const r = Object.assign({}, vacio);
    r.datos = { compras: ev.length, intervalos: obs.filter(o => o.tipo === 'intervalo').length, usados: usados.length, descartados: obs.length - usados.length };
    r.ultimaCompra = ult.fecha;
    r.estado = usados.length ? 'calculado' : 'aprendiendo';
    r.fuente = fuente;
    if (dias) {
      dias = Math.max(1, dias);
      r.dias = Math.max(1, Math.round(dias));
      r.diasEstaVez = Math.max(1, Math.round(dias * rUlt));
      const z = 1.2816;
      r.rango = [Math.max(1, Math.round(dias * rUlt * Math.exp(-z * spred))), Math.max(1, Math.round(dias * rUlt * Math.exp(z * spred)))];
      const k = usados.length;
      let cn = fuente === 'grupo' ? .15 : (1 - Math.exp(-k / 3)) * Math.exp(-Math.max(0, spred - .2) * 1.5);
      if (fuente === 'acabo') cn = Math.min(cn, .3);
      r.confianzaN = Math.round(Math.max(0, Math.min(1, cn)) * 100) / 100;
      r.confianza = (r.confianzaN >= .55 && k >= 4) ? 'alta' : (r.confianzaN >= .3 && k >= 2) ? 'media' : 'baja';
      r.comprasPorMes = r1(30.44 / dias);
      if (falta) { r.proxima = null; r.proximaRango = null; r.uso = 1; r.nivel = 'ya'; r.quedan = 0; }
      else {
        r.proxima = suma(ult.fecha, r.diasEstaVez);
        r.proximaRango = [suma(ult.fecha, r.rango[0]), suma(ult.fecha, r.rango[1])];
        const trans = hoy ? dif(ult.fecha, hoy) : 0;
        r.uso = Math.round(trans / r.diasEstaVez * 100) / 100;
        r.quedan = r.diasEstaVez - trans;
        r.nivel = r.uso >= 1 ? 'ya' : r.uso >= .85 ? 'pronto' : r.uso >= .5 ? 'medio' : 'fresco';
      }
    }
    if (acaboObs) r.acabo = { ultimaVez: acaboObs.g };

    // tendencia: las últimas compras contra las de antes
    if (usados.length >= 4) {
      const nR = usados.length >= 6 ? 3 : 2, ord = usados.slice().sort((a, b) => a.i - b.i);
      const rec = mediana(ord.slice(-nR).map(o => o.norm)), ant = mediana(ord.slice(0, -nR).map(o => o.norm));
      const ratio = rec / ant, pct = Math.round((ratio - 1) * 100);
      const dir = ratio <= .8 ? 'mas_rapido' : ratio >= 1.25 ? 'mas_lento' : 'estable';
      r.tendencia = { dir, cambioPct: pct, texto: dir === 'mas_rapido' ? 'Últimamente se gasta más rápido' : dir === 'mas_lento' ? 'Últimamente te dura más' : 'Se gasta al mismo ritmo de siempre' };
    }

    // cantidad y consumo
    if (qHab && uMostrar) {
      const habN = qHab / fMostrar, ultN = ult.base != null ? ult.base / fMostrar : null;
      r.cantidad = { ultima: ultN != null ? { n: r1(ultN), u: uMostrar, texto: textoCant(ultN, uMostrar) } : null, habitual: { n: r1(habN), u: uMostrar, texto: textoCant(habN, uMostrar) }, relativa: r1(rUlt) };
    }
    if (dias) {
      if (qHab && uMostrar) {
        const sem = qHab / fMostrar / dias * 7, mes = qHab / fMostrar / dias * 30.44;
        r.porSemana = { n: r1(sem), u: uMostrar, texto: textoCant(sem, uMostrar) + ' por semana' };
        r.porMes = { n: r1(mes), u: uMostrar, texto: textoCant(mes, uMostrar) + ' al mes' };
      } else {
        const sem = 7 / dias, mes = 30.44 / dias;
        const tx = x => x >= .95 ? fmtN(x) + (Math.round(x * 10) === 10 ? ' vez' : ' veces') : '1 vez cada ' + (dias < 21 ? Math.round(dias / 7 * 10) / 10 + ' semanas' : Math.round(dias / 30.44 * 10) / 10 + ' meses');
        r.porSemana = { n: r1(sem), u: 'veces', texto: sem >= .95 ? tx(sem) + ' por semana' : tx(sem) };
        r.porMes = { n: r1(mes), u: 'veces', texto: mes >= .95 ? tx(mes) + ' al mes' : tx(mes) };
      }
      r.porSemana.texto = r.porSemana.texto.replace(/,0 /, ' ');
    }

    // historial (últimas 12)
    const atip = new Set(obs.filter(o => o.atipico && o.tipo === 'intervalo').map(o => o.i));
    r.historial = ev.slice(-12).map(e => {
      const i = ev.indexOf(e);
      return { fecha: e.fecha, cantidad: e.base != null && uMostrar ? textoCant(e.base / fMostrar, uMostrar) : (detNom(e.items[0].nombre) || null), dias: i + 1 < ev.length ? dif(e.fecha, ev[i + 1].fecha) : null, atipico: atip.has(i) };
    });

    // meses: cuándo se compró más o menos (últimos 6, desde la primera compra)
    const ref = hoy || ult.fecha;
    const meses = [];
    for (let k = 5; k >= 0; k--) { const d = new Date(Date.UTC(+ref.slice(0, 4), +ref.slice(5, 7) - 1 - k, 1)); meses.push(d.toISOString().slice(0, 7)); }
    const cuenta = {}; ev.forEach(e => { const m = e.fecha.slice(0, 7); cuenta[m] = (cuenta[m] || 0) + 1; });
    r.meses = meses.map(m => ({ mes: m, veces: cuenta[m] || 0 }));
    const validos = r.meses.filter(x => x.mes >= ev[0].fecha.slice(0, 7) && x.mes < ref.slice(0, 7));   // meses completos con el producto ya existiendo
    if (validos.length >= 3 && validos.reduce((s, x) => s + x.veces, 0) >= 3) {
      const mx = Math.max(...validos.map(x => x.veces)), mn = Math.min(...validos.map(x => x.veces));
      if (mx - mn >= 2) { r.mesMas = validos.filter(x => x.veces === mx).pop().mes; r.mesMenos = validos.filter(x => x.veces === mn).pop().mes; }
    }

    // patrón: inicio / mitad / fin de mes, o un día de la semana
    r.patron = patronDe(ev.map(e => e.fecha), 4, .6, 'Lo sueles comprar');

    r.nota = nota(r, p);
    return r;
  }

  function patronDe(fechas, minN, minFrac, prefijo) {
    const n = fechas.length; if (n < minN) return null;
    const t = [0, 0, 0]; fechas.forEach(f => { const d = +f.slice(8, 10); t[d <= 10 ? 0 : d <= 20 ? 1 : 2]++; });
    const im = t.indexOf(Math.max(...t));
    if (t[im] / n >= minFrac && binomCola(t[im], n, 1 / 3) < .1) {
      const tipo = ['inicio_mes', 'mitad_mes', 'fin_mes'][im];
      return { tipo, texto: prefijo + ' ' + ['a inicio de mes', 'a mitad de mes', 'a fin de mes'][im] };
    }
    const w = [0, 0, 0, 0, 0, 0, 0]; fechas.forEach(f => { w[new Date(ms(f)).getUTCDay()]++; });
    const iw = w.indexOf(Math.max(...w));
    if (w[iw] >= 3 && w[iw] / n >= .5 && binomCola(w[iw], n, 1 / 7) < .05) return { tipo: 'dia_semana', dia: iw, texto: prefijo + ' los ' + DIAS_S[iw] };
    return null;
  }

  const plD = n => n + (n === 1 ? ' día' : ' días');
  const enPal = d => d < 11 || (d < 25 && Math.abs(d / 7 - Math.round(d / 7)) > .2) ? plD(d) : d < 25 ? (Math.round(d / 7) === 1 ? 'una semana' : 'unas ' + Math.round(d / 7) + ' semanas') : d < 45 ? 'un mes' : 'unos ' + Math.round(d / 30.44) + ' meses';
  function nota(r, p) {
    if (r.estado === 'sin') return 'Todavía no hay compras registradas.';
    const partes = [];
    if (r.fuente === 'grupo') partes.push('Solo hay una compra. Mientras aprendo, calculo con lo que duran cosas parecidas: ~' + enPal(r.diasEstaVez) + '.');
    else if (r.fuente === 'acabo') partes.push('La última vez duró ' + plD(r.acabo.ultimaVez) + '. Con una compra más lo afino.');
    else if (r.dias) partes.push('Te dura ' + (r.dias < 11 ? '~' : '') + enPal(r.dias) + (r.rango && r.confianza !== 'alta' ? ' (entre ' + r.rango[0] + ' y ' + r.rango[1] + ' días)' : '') + '.');
    else partes.push('Aprendiendo: falta una compra más para saber cuánto dura.');
    if (r.cantidad && r.cantidad.relativa >= 1.4 && r.diasEstaVez && r.proxima) partes.push('La última vez compraste ' + (r.cantidad.relativa >= 1.9 && r.cantidad.relativa <= 2.1 ? 'el doble' : 'más de lo normal') + ': debería alcanzar hasta el ' + fCorta(r.proxima) + '.');
    else if (r.cantidad && r.cantidad.relativa <= .7 && r.diasEstaVez && r.proxima) partes.push('La última vez compraste menos de lo normal: se acabaría hacia el ' + fCorta(r.proxima) + '.');
    if (r.tendencia.dir === 'mas_rapido' || r.tendencia.dir === 'mas_lento') partes.push(r.tendencia.texto + ' (' + (r.tendencia.cambioPct > 0 ? '+' : '') + r.tendencia.cambioPct + '%).');
    if (r.patron) partes.push(r.patron.texto + '.');
    if (r.mesMas && r.mesMas.slice(0, 7) !== (r.mesMenos || '')) { const mx = r.meses.find(x => x.mes === r.mesMas); if (mx && mx.veces >= 2) partes.push('Donde más lo compraste fue en ' + nomMes(r.mesMas) + '.'); }
    if (r.datos.descartados) partes.push('Ignoré ' + r.datos.descartados + (r.datos.descartados === 1 ? ' compra rara' : ' compras raras') + ' para no despistarme.');
    return partes.slice(0, 3).join(' ');
  }

  /* ── todos los productos: primero los que tienen historial, después los de 1 compra con el promedio del grupo ── */
  const out = {};
  const pendientes = [];
  for (const p of productos) {
    if (!p || !p.id) continue;
    const r = modelaProducto(p, null);
    out[idc(p.id)] = r;
    if (r.estado === 'aprendiendo') pendientes.push(p);
  }
  const grupoDias = {}, todos = [];
  productos.forEach(p => { const r = p && out[idc(p.id)]; if (r && r.estado === 'calculado' && r.fuente === 'historial') { (grupoDias[p.grupo || 'Otros'] = grupoDias[p.grupo || 'Otros'] || []).push(r.dias); todos.push(r.dias); } });
  for (const p of pendientes) {
    const g = grupoDias[p.grupo || 'Otros'];
    const prior = g && g.length >= 2 ? mediana(g) : todos.length >= 3 ? mediana(todos) : null;
    if (prior) out[idc(p.id)] = modelaProducto(p, prior);
  }

  /* ── global: cada cuánto se merca, qué día, qué meses ── */
  const diasMercado = [...new Set(Object.values(comprasDe).flat().map(c => c.fecha))].sort();
  const gaps = []; for (let i = 1; i < diasMercado.length; i++) gaps.push(dif(diasMercado[i - 1], diasMercado[i]));
  const ref = hoy || diasMercado[diasMercado.length - 1] || '2000-01-01';
  const meses = [];
  for (let k = 5; k >= 0; k--) { const d = new Date(Date.UTC(+ref.slice(0, 4), +ref.slice(5, 7) - 1 - k, 1)); meses.push(d.toISOString().slice(0, 7)); }
  const cuentaM = {};
  Object.values(comprasDe).forEach(l => eventos(l).forEach(e => { const m = e.fecha.slice(0, 7); cuentaM[m] = (cuentaM[m] || 0) + e.items.length; }));
  const global = {
    mercadoCadaDias: gaps.length ? Math.round(mediana(gaps.slice(-20))) : null,
    diaSemana: null, patronMes: null,
    meses: meses.map(m => ({ mes: m, compras: cuentaM[m] || 0 })),
    mesMas: null, mesMenos: null,
    rapido: Object.keys(out).filter(id => out[id].tendencia.dir === 'mas_rapido'),
    nota: null
  };
  const pd = patronDe(diasMercado.slice(-30), 6, .5, 'Mercas más');
  if (pd && pd.tipo === 'dia_semana') global.diaSemana = { d: pd.dia, texto: 'Sueles mercar los ' + DIAS_S[pd.dia] };
  else if (pd) global.patronMes = { tipo: pd.tipo, texto: pd.texto + (pd.tipo !== 'mitad_mes' ? ' (después de la quincena)' : '') };
  const completos = global.meses.filter(x => x.mes < ref.slice(0, 7) && diasMercado.length && x.mes >= diasMercado[0].slice(0, 7));
  if (completos.length >= 3) {
    const vals = completos.map(x => x.compras), md = mediana(vals), mx = Math.max(...vals), mn = Math.min(...vals);
    if (mx > mn) {
      global.mesMas = completos.filter(x => x.compras === mx).pop().mes; global.mesMenos = completos.filter(x => x.compras === mn).pop().mes;
      if (md > 0 && mx >= 1.3 * md && mx - md >= 2) global.nota = 'En ' + nomMes(global.mesMas) + ' compraste más que de costumbre.';
      else if (md > 0 && mn <= .7 * md && md - mn >= 2) global.nota = 'En ' + nomMes(global.mesMenos) + ' compraste menos que de costumbre.';
    }
  }
  if (!global.nota && global.mercadoCadaDias) global.nota = 'Sueles mercar cada ' + plD(global.mercadoCadaDias) + '.';

  return { v: 1, hoy, productos: out, global };
}


const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const prop = (pg, n) => (pg.properties || {})[n];
const fecha = (pr) => pr && pr.date && pr.date.start ? pr.date.start : null;
const paginas = (nodo) => { try { return $(nodo).all().flatMap(i => Array.isArray(i.json.results) ? i.json.results : (i.json && i.json.object === 'page' ? [i.json] : [])); } catch (e) { return []; } };
const hoy = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);   // hora de Colombia

const productos = paginas('Productos').map(pg => ({
  id: pg.id,
  nombre: txt((prop(pg, 'Nombre') || {}).title),
  grupo: (prop(pg, 'Grupo') || {}).select ? prop(pg, 'Grupo').select.name : null,
  falta: !!(prop(pg, 'Falta') || {}).checkbox,
  marcadoEl: fecha(prop(pg, 'Marcado el'))
}));
const compras = paginas('Compras').map(pg => {
  const c = prop(pg, 'Cantidad');                       // opcional: número o texto, si el flujo de compras lo empieza a guardar
  const cantidad = !c ? undefined : c.type === 'number' ? (c.number == null ? undefined : c.number) : (txt(c.rich_text) || undefined);
  return {
    productoId: txt((prop(pg, 'ID producto') || {}).rich_text) || null,
    fecha: (fecha(prop(pg, 'Fecha')) || pg.created_time || '').slice(0, 10),
    nombre: txt((prop(pg, 'Nombre') || {}).title),
    cantidad,
    acaboAnterior: fecha(prop(pg, 'Se acabó la anterior')) || undefined   // opcional
  };
});

const r = calcularDuracion({ hoy, productos, compras });
r.ok = true;
r.calculado = new Date().toISOString();
if (productos.length) $getWorkflowStaticData('global').duraCache = { t: Date.now(), r };
return [{ json: r }];
